const $=s=>document.querySelector(s),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=x=>Number(x).toLocaleString('pt-BR');let index=Math.max(0,Math.min(DECK.slides.length-1,(parseInt(location.hash.slice(1))||1)-1)),running=false,elapsed=0,last=0;
function content(s,i){let cols=s.columns?'<div class="cols" style="grid-template-columns:repeat('+s.columns.length+',1fr)">'+s.columns.map(c=>'<div class="col"><h2>'+esc(c.heading)+'</h2><p>'+esc(c.body)+'</p></div>').join('')+'</div>':'';let base='<span class="page-number">'+String(i+1).padStart(2,'0')+'</span>';if(s.kind==='cover')return base+'<div class="photo"></div><div class="cover-text"><img class="fumec" src="../assets/fumec-logo.png" alt="Universidade FUMEC"><div class="institution">DOUTORADO EM ADMINISTRAÇÃO</div><h1>'+esc(s.title)+'</h1><p class="subtitle">'+esc(s.subtitle)+'</p><div class="author">Débora Cristina Coutinho Vilas Bôas<br>Orientadora: Profa. Dra. Suzana Rodrigues</div><p class="event">27 de outubro de 2026 · 15h<br>Qualificação do projeto · roteiro de 20 minutos</p></div>';base+='<p class="group">'+esc(s.group)+'</p><h1 class="'+(s.title.length>72?'long':'')+'">'+esc(s.title)+'</h1><p class="subtitle">'+esc(s.subtitle)+'</p>';if(s.kind==='statement')base+='<div class="quote">'+esc(s.quote)+'</div>'+cols;else if(s.kind==='data')base+='<table class="table"><thead><tr>'+s.rows[0].map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+s.rows.slice(1).map(r=>'<tr>'+r.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';else if(s.kind==='timeline')base+='<table class="table"><thead><tr><th>Atividade · 2026 → 2027</th>'+s.months.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+s.timeline.map(r=>'<tr><td>'+esc(r[0])+'</td>'+r.slice(1).map(x=>'<td class="'+(x?'active':'')+'">'+(x?'●':'')+'</td>').join('')+'</tr>').join('')+'</tbody></table>';else if(s.kind==='chart')base+='<div class="chart-layout"><div class="bars">'+s.values.map((v,j)=>'<div class="bar-wrap"><div class="bar" style="height:'+v/7000*100+'%"><div class="bar-value">'+num(v)+'</div></div><div class="bar-year">'+s.categories[j]+'</div></div>').join('')+'</div><div class="stat"><strong>'+s.stat+'</strong><p>'+esc(s.takeaway)+'</p></div></div>';else base+=cols;return base+'<p class="bottom">'+esc(s.bottom||'')+'</p>'}
const nodes=DECK.slides.map((s,i)=>{let e=document.createElement('section');e.className='slide '+s.kind+(['statement','closing'].includes(s.kind)?' dark':'');e.innerHTML=content(s,i);e.hidden=true;$('#canvas').append(e);$('#jump').add(new Option((i+1)+'. '+s.title,i));return e});
function fit(){let r=$('#stage').getBoundingClientRect();$('#canvas').style.transform='scale('+Math.min(r.width/1280,r.height/720)+')'}
function show(i){index=Math.max(0,Math.min(nodes.length-1,i));nodes.forEach((n,j)=>n.hidden=j!==index);$('#position').textContent=(index+1)+' / '+nodes.length;$('#jump').value=index;$('#notes-text').textContent=DECK.slides[index].notes;let secs=DECK.slides[index].seconds,start=DECK.slides.slice(0,index).reduce((a,s)=>a+s.seconds,0);$('#pace').textContent='Fala sugerida: '+secs+' s · início em '+Math.floor(start/60)+':'+String(start%60).padStart(2,'0')+' · ← → avançar · F tela cheia · N notas';$('#progress').style.width=(index+1)/nodes.length*100+'%';$('#prev').disabled=index===0;$('#next').disabled=index===nodes.length-1;history.replaceState(null,'','#'+(index+1));$('#announcement').textContent='Slide '+(index+1)+': '+DECK.slides[index].title;fit()}
async function full(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(e){$('#announcement').textContent='Use o modo de tela cheia do navegador, F11.'}}
$('#next').onclick=()=>show(index+1);$('#prev').onclick=()=>show(index-1);$('#jump').onchange=e=>show(+e.target.value);$('#fullscreen').onclick=full;$('#notes-toggle').onclick=()=>$('#notes').hidden=!$('#notes').hidden;$('#timer').onclick=()=>{running=!running;last=Date.now();$('#timer').textContent=running?'Ⅱ Pausar tempo':'▶ Retomar tempo'};setInterval(()=>{if(running){elapsed+=(Date.now()-last)/1000;last=Date.now()}$('#clock').textContent=String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(Math.floor(elapsed%60)).padStart(2,'0')+' / 20:00'},500);window.addEventListener('resize',fit);document.addEventListener('fullscreenchange',fit);window.addEventListener('keydown',e=>{if(['SELECT','INPUT','TEXTAREA'].includes(e.target.tagName))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(index+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(index-1)}if(e.key==='Home')show(0);if(e.key==='End')show(nodes.length-1);if(e.key.toLowerCase()==='f')full();if(e.key.toLowerCase()==='n')$('#notes-toggle').click()});show(index);window.DECK_READY=true;
